1	package review
2	
3	import (
4		"encoding/json"
5		"strings"
6	
7		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
8	)
9	
10	// trailFindingsJSONInstructions is the trail-mode output contract. Reviewers
11	// and the judge end with this JSON line so posting reads their findings
12	// structurally instead of interpreting prose. The example line must parse
13	// with splitTrailJSON; a test enforces that.
14	const trailFindingsJSONInstructions = `Final line (required, read by a program):
15	End your output with exactly one line holding only this JSON object, with no code fence and nothing after it:
16	{"summary":"one-sentence verdict","comments":[{"severity":"high","body":"bug; impact; fix","location":{"granularity":"line","file_path":"path/to/file.go","start_line":42}}]}
17	- Add one comment per actionable finding reported above, however it is laid out (bullets, headings, numbered or bold sections), with the same severity: high, medium, or low.
18	- Give each comment the file and line the finding cites; every file:line in a finding above must fall in some comment's location.
19	- location.granularity is line (with start_line), range (with start_line and end_line), file, or whole_change.
20	- If nothing is actionable, use an empty array: "comments":[].
21	- This line is required even where other instructions say to output nothing else.`
22	
23	// maxTrailJSONLines bounds the backward scan for a pretty-printed JSON block.
24	const maxTrailJSONLines = 200
25	
26	// TrailComment is one finding in the trail JSON contract.
27	type TrailComment struct {
28		Severity   string        `json:"severity"`
29		Confidence *float64      `json:"confidence,omitempty"`
30		Body       string        `json:"body"`
31		Location   TrailLocation `json:"location"`
32	}
33	
34	// TrailLocation anchors a TrailComment to the change.
35	type TrailLocation struct {
36		Granularity  string `json:"granularity"`
37		FilePath     string `json:"file_path,omitempty"`
38		StartLine    int    `json:"start_line,omitempty"`
39		EndLine      int    `json:"end_line,omitempty"`
40		SelectedText string `json:"selected_text,omitempty"`
41	}
42	
43	// TrailReport is what a trail-mode run posts: structured comments from
44	// reviews that honored the JSON contract, and the prose, with any contract
45	// line removed, of those that did not. At least one of the two is set.
46	type TrailReport struct {
47		Comments []TrailComment
48		Prose    string
49	}
50	
51	// trailReportFor decides what a trail-mode run posts. It returns post=false
52	// only when the JSON contract reports no findings and nothing in the prose
53	// contradicts that; every malformed or contradictory case posts, so a
54	// misbehaving model costs an extra finding rather than a lost one. A posted
55	// report is empty only when the output had nothing readable. When a judge
56	// ran, its verdict decides: it is asked to drop unsupported claims.
57	func trailReportFor(summary reviewtypes.RunSummary, aggregateOutput string) (TrailReport, bool) {
58		if verdict := strings.TrimSpace(aggregateOutput); verdict != "" {
59			prose, comments, ok := splitTrailJSON(verdict)
60			if !contractCoversProse(prose, comments, ok) {
61				if prose == "" {
62					// A JSON-only reply without a summary has no prose of its own.
63					prose = combinedReviewNarratives(usableAgentRuns(summary))
64				}
65				return TrailReport{Prose: prose}, true
66			}
67			return TrailReport{Comments: comments}, len(comments) > 0
68		}
69		var merged []TrailComment
70		var unstructured []reviewtypes.AgentRun
71		for _, run := range usableAgentRuns(summary) {
72			prose, comments, ok := splitTrailJSON(reportText(run.Buffer))
73			if !contractCoversProse(prose, comments, ok) {
74				unstructured = append(unstructured, run)
75				continue
76			}
77			merged = append(merged, comments...)
78		}
79		report := TrailReport{Comments: merged, Prose: combinedReviewNarratives(unstructured)}
80		return report, len(merged) > 0 || len(unstructured) > 0
81	}
82	
83	// contractCoversProse reports whether a valid contract can be posted in place
84	// of its prose. The contract is trusted: its comments are the findings. Only
85	// an empty array that the prose explicitly contradicts, with a severity
86	// marker or a non-approving verdict, posts the prose instead.
87	func contractCoversProse(prose string, comments []TrailComment, ok bool) bool {
88		if !ok {
89			return false
90		}
91		return len(comments) > 0 || !proseReportsFindings(prose)
92	}
93	
94	// listItemOrLine returns line without surrounding space and, for a list
95	// item, without its bullet.
96	func listItemOrLine(line string) string {
97		trimmed := strings.TrimSpace(line)
98		if item, ok := listItemText(trimmed); ok {
99			return item
100		}
101		return trimmed
102	}
103	
104	// reportText returns a reviewer's report: the last stretch of text between
105	// tool calls that ends with a valid contract line, or "" if none does. It is
106	// found by the contract line rather than by position, so a tool call after
107	// the report does not hide it, and earlier exploration narration, whose
108	// bullets ("I'll check:\n- retry.go") are not findings, is left out.
109	func reportText(buf []reviewtypes.Event) string {
110		stretches := textStretches(buf)
111		for i := len(stretches) - 1; i >= 0; i-- {
112			if _, _, ok := splitTrailJSON(stretches[i]); ok {
113				return stretches[i]
114			}
115		}
116		return ""
117	}
118	
119	// textStretches splits buf's assistant text at tool calls. A tool call inside
120	// a message, where the next text continues it as a delta, does not split it.
121	func textStretches(buf []reviewtypes.Event) []string {
122		var stretches []string
123		var segment []reviewtypes.Event
124		afterToolCall := false
125		for _, ev := range buf {
126			switch ev := ev.(type) {
127			case reviewtypes.ToolCall:
128				afterToolCall = true
129			case reviewtypes.AssistantText:
130				if afterToolCall && !ev.Delta && len(segment) > 0 {
131					stretches = append(stretches, joinAssistantText(segment))
132					segment = nil
133				}
134				afterToolCall = false
135				segment = append(segment, ev)
136			}
137		}
138		if len(segment) > 0 {
139			stretches = append(stretches, joinAssistantText(segment))
140		}
141		return stretches
142	}
143	
144	// splitTrailJSON separates a trailing contract-shaped JSON object (one line,
145	// a fenced block, or a pretty-printed block, with a "summary" or "comments"
146	// key) from the prose before it, so a malformed contract is never posted as
147	// finding text. Other trailing JSON, such as a config snippet quoted as
148	// evidence, stays in the prose. A JSON-only reply contributes its summary as
149	// the prose instead. ok reports a valid contract: a "comments" array.
150	// Entries without a body are dropped.
151	func splitTrailJSON(text string) (prose string, comments []TrailComment, ok bool) {
152		prose, payload, found := splitTrailJSONPayload(text)
153		if !found {
154			return prose, nil, false
155		}
156		if prose == "" {
157			var summary string
158			if json.Unmarshal(payload["summary"], &summary) == nil {
159				prose = strings.TrimSpace(summary)
160			}
161		}
162		comments, ok = decodeTrailComments(payload["comments"])
163		return prose, comments, ok
164	}
165	
166	// splitTrailJSONPayload finds a trailing contract-shaped JSON object and
167	// returns the prose before it and its decoded keys. found is false, with
168	// the whole text as prose, when there is none.
169	func splitTrailJSONPayload(text string) (prose string, payload map[string]json.RawMessage, found bool) {
170		text = strings.TrimSpace(text)
171		lines := strings.Split(text, "\n")
172		end := len(lines)
173		fenced := end > 1 && strings.TrimSpace(lines[end-1]) == "```"
174		if fenced {
175			end--
176		}
177		for start := end - 1; start >= 0 && start >= end-maxTrailJSONLines; start-- {
178			if !strings.HasPrefix(strings.TrimSpace(lines[start]), "{") {
179				continue
180			}
181			payload = nil
182			if err := json.Unmarshal([]byte(strings.Join(lines[start:end], "\n")), &payload); err != nil {
183				continue
184			}
185			_, hasSummary := payload["summary"]
186			_, hasComments := payload["comments"]
187			if !hasSummary && !hasComments {
188				break
189			}
190			proseEnd := start
191			if fenced && proseEnd > 0 && strings.HasPrefix(strings.TrimSpace(lines[proseEnd-1]), "```") {
192				proseEnd--
193			}
194			return strings.TrimSpace(strings.Join(lines[:proseEnd], "\n")), payload, true
195		}
196		return text, nil, false
197	}
198	
199	func decodeTrailComments(raw json.RawMessage) ([]TrailComment, bool) {
200		if !strings.HasPrefix(strings.TrimSpace(string(raw)), "[") {
201			return nil, false
202		}
203		var decoded []TrailComment
204		if err := json.Unmarshal(raw, &decoded); err != nil {
205			return nil, false
206		}
207		comments := []TrailComment{}
208		for _, comment := range decoded {
209			if strings.TrimSpace(comment.Body) != "" {
210				comments = append(comments, comment)
211			}
212		}
213		return comments, true
214	}
215	
216	// stripTrailJSON removes a valid trailing contract line for display. Only a
217	// run that asked for the line has one; elsewhere a trailing JSON block is the
218	// reviewer's own text and stays.
219	func stripTrailJSON(text string, trailFindingsJSON bool) string {
220		if !trailFindingsJSON {
221			return text
222		}
223		if prose, _, ok := splitTrailJSON(text); ok {
224			return prose
225		}
226		return text
227	}
228	
229	// proseReportsFindings reports whether prose explicitly contradicts an empty
230	// comments array: a line opening with a severity marker or a feedback label
231	// such as "Nits:", or a verdict, labeled or not, that itself says there is
232	// feedback. A severity group label such as "### High" over "None." is not
233	// one.
234	func proseReportsFindings(prose string) bool {
235		for _, line := range strings.Split(prose, "\n") {
236			if severityGroupLabel(line) != "" {
237				continue
238			}
239			lower := strings.ToLower(trimMarkdownEmphasis(listItemOrLine(line)))
240			if after, found := strings.CutPrefix(lower, "verdict"); found {
241				lower = trimMarkdownEmphasis(strings.TrimLeft(after, ":-—– "))
242			}
243			if startsWithSeverityMarker(lower) {
244				return true
245			}
246			for _, prefix := range []string{
247				"request changes", "request_changes", "changes requested", "approve with nits",
248				"needs changes", "needs work", "changes needed",
249				"nits:", "issues:", "concerns:", "suggestions:", "findings:", "problems:", "blocking:",
250			} {
251				if strings.HasPrefix(lower, prefix) {
252					return true
253				}
254			}
255		}
256		return false
257	}
258	
259	func trimMarkdownEmphasis(s string) string {
260		return strings.TrimLeft(s, "#>*_` ")
261	}
262	
263	func isUnindented(line string) bool {
264		return line == strings.TrimLeft(line, " \t")
265	}
266	
267	var severityMarkers = []string{"critical", "high", "medium", "low", "p0", "p1", "p2", "p3", "nit"}
268	
269	// startsWithSeverityMarker reports whether line, after leading Markdown
270	// emphasis, opens with a severity tag: bracketed ("[high]"), delimited
271	// ("high —", "p2:"), closed by emphasis ("**High** ..."), or alone (a "### High"
272	// heading). A word that merely starts with a marker ("Highlights") is not one.
273	func startsWithSeverityMarker(line string) bool {
274		return LeadingSeverity(line) != ""
275	}
276	
277	// LeadingSeverity returns the severity tag line opens with, in lower case, as
278	// startsWithSeverityMarker recognizes it, or "" if there is none.
279	func LeadingSeverity(line string) string {
280		lower := strings.ToLower(trimMarkdownEmphasis(strings.TrimSpace(line)))
281		for _, marker := range severityMarkers {
282			if strings.HasPrefix(lower, "["+marker+"]") {
283				return marker
284			}
285			rest, found := strings.CutPrefix(lower, marker)
286			if !found {
287				continue
288			}
289			if strings.TrimSpace(rest) == "" {
290				return marker
291			}
292			for _, suffix := range []string{" —", " –", " -", ":", "*", "_"} {
293				if strings.HasPrefix(rest, suffix) {
294					return marker
295				}
296			}
297		}
298		return ""
299	}
300	
301	// severityGroupLabel returns, in lower case, the severity that line labels a
302	// group of findings with, or "": an unindented line holding only a severity
303	// ("### High", "**Low:**", "Nits:"), or a heading whose first word is one
304	// followed by a delimiter or a qualifier ("### High severity",
305	// "## P1 — must fix"). "## High Level Summary" is not one.
306	func severityGroupLabel(line string) string {
307		if label := severityLabel(line); label != "" {
308			return label
309		}
310		words := strings.Fields(headingTitle(line))
311		if len(words) == 0 {
312			return ""
313		}
314		label := severityLabel(words[0])
315		if label != "" && (len(words) == 1 || strings.HasSuffix(words[0], ":") || isSeverityQualifier(words[1])) {
316			return label
317		}
318		return ""
319	}
320	
321	func isSeverityQualifier(word string) bool {
322		word = strings.ToLower(strings.Trim(word, "*_`:"))
323		if strings.HasPrefix(word, "(") {
324			return true
325		}
326		switch word {
327		case "—", "–", "-", "severity", "priority", "issues", "findings", "risk":
328			return true
329		}
330		return false
331	}
332	
333	// headingLevel returns the level of an unindented Markdown "#" heading, or 0.
334	func headingLevel(line string) int {
335		level := len(line) - len(strings.TrimLeft(line, "#"))
336		if level == 0 || !strings.HasPrefix(line[level:], " ") {
337			return 0
338		}
339		return level
340	}
341	
342	// headingTitle returns the text of a Markdown "#" heading, or "".
343	func headingTitle(line string) string {
344		if headingLevel(line) == 0 {
345			return ""
346		}
347		return strings.TrimSpace(strings.TrimLeft(line, "#"))
348	}
349	
350	// severityLabel returns, in lower case, the severity an unindented line
351	// holding only a severity label ("### High", "**Low:**", "Nits:") names, or "".
352	func severityLabel(line string) string {
353		if !isUnindented(line) {
354			return ""
355		}
356		label := strings.TrimLeft(trimMarkdownEmphasis(strings.TrimSpace(line)), "[")
357		label = strings.ToLower(strings.TrimRight(label, ":*_`] "))
358		for _, marker := range severityMarkers {
359			if label == marker || label == marker+"s" {
360				return label
361			}
362		}
363		return ""
364	}
365	
366	// isNoFindingsText reports whether text only says a section is empty, such
367	// as "None." under a severity heading, so the splitter does not post it.
368	func isNoFindingsText(text string) bool {
369		return noFindingsTexts[strings.ToLower(strings.Trim(text, "*_`.!:() \t"))]
370	}
371	
372	var noFindingsTexts = map[string]bool{
373		"": true, "-": true, "—": true, "–": true, "none": true, "n/a": true, "nothing": true,
374		"none found": true, "no issues": true, "no issues found": true, "no findings": true, "nothing to report": true,
375	}
376	
377	// ProseFinding is one top-level finding in prose. Severity is the label of
378	// the severity group it sits in ("high", "p2"), or "" outside one.
379	type ProseFinding struct {
380		Text     string
381		Severity string
382	}
383	
384	// SplitProseFindings splits prose that is posted without a usable contract
385	// into findings: top-level list items and lines that open with a severity
386	// marker, each with the lines that continue it. A severity group label
387	// ("### High", "**Low:**") sets the severity of the findings below it rather
388	// than being one; in a group, other text is a finding too, and a deeper
389	// heading starts a finding that holds everything up to the next heading. A
390	// group ends at a heading at its level or above, or at a placeholder such as
391	// "None." where a finding would start, so a closing summary is not posted.
392	// It only shapes posted prose; whether prose is posted does not depend on it.
393	func SplitProseFindings(prose string) []ProseFinding {
394		var findings []ProseFinding
395		var current strings.Builder
396		group, groupLevel := "", 0
397		// section marks a finding opened at a deeper heading, which takes every
398		// line up to the next heading.
399		section := false
400		flush := func() {
401			text := strings.TrimSpace(current.String())
402			current.Reset()
403			section = false
404			if text != "" {
405				findings = append(findings, ProseFinding{Text: text, Severity: group})
406			}
407		}
408		for _, line := range strings.Split(strings.TrimSpace(prose), "\n") {
409			if label := severityGroupLabel(line); label != "" {
410				flush()
411				group, groupLevel = label, headingLevel(line)
412				continue
413			}
414			if level := headingLevel(line); level > 0 && group != "" {
415				flush()
416				if groupLevel > 0 && level > groupLevel {
417					current.WriteString(headingTitle(line))
418					section = true
419				} else {
420					group = ""
421				}
422				continue
423			}
424			text := listItemOrLine(line)
425			if section {
426				if titleOnly := !strings.Contains(current.String(), "\n"); titleOnly && (text == "" || isNoFindingsText(text)) {
427					if text != "" {
428						// "### Security\nNone." reports nothing.
429						current.Reset()
430						section = false
431					}
432					continue
433				}
434				current.WriteString("\n" + line)
435				continue
436			}
437			item, isItem := topLevelListItemText(line)
438			if isItem || (isUnindented(line) && startsWithSeverityMarker(line)) {
439				flush()
440				switch {
441				case isNoFindingsText(text):
442					group = ""
443				case isItem:
444					current.WriteString(item)
445				default:
446					current.WriteString(text)
447				}
448				continue
449			}
450			if current.Len() == 0 {
451				if group == "" || text == "" {
452					continue
453				}
454				if isNoFindingsText(text) {
455					group = ""
456					continue
457				}
458			} else {
459				current.WriteByte('\n')
460			}
461			current.WriteString(line)
462		}
463		flush()
464		return findings
465	}
466	
467	func topLevelListItemText(line string) (string, bool) {
468		if !isUnindented(line) {
469			return "", false
470		}
471		item, ok := listItemText(strings.TrimSpace(line))
472		return item, ok && item != ""
473	}
474	
475	// listItemText returns the text of a Markdown list item ("- ", "* ", "+ ",
476	// "• ", "1. ", "1) ") and whether trimmed, a line without surrounding space,
477	// is one.
478	func listItemText(trimmed string) (string, bool) {
479		for _, bullet := range []string{"- ", "* ", "+ ", "• "} {
480			if item, found := strings.CutPrefix(trimmed, bullet); found {
481				return strings.TrimSpace(item), true
482			}
483		}
484		digits := len(trimmed) - len(strings.TrimLeft(trimmed, "0123456789"))
485		if digits == 0 {
486			return "", false
487		}
488		for _, delim := range []string{". ", ") "} {
489			if item, found := strings.CutPrefix(trimmed[digits:], delim); found {
490				return strings.TrimSpace(item), true
491			}
492		}
493		return "", false
494	}
