// A contract's comments are posted only when they cover every finding the
// prose reports, however the prose is laid out.
func TestTrailReportProseLayouts(t *testing.T) {
	t.Parallel()
	reviewers := judgeReviewers()

	t.Run("comments grouped under severity headings are posted as structured findings", func(t *testing.T) {
		t.Parallel()
		prose := "request changes\n### High\n- [high] retry.go:42 — Loop ignores ctx cancel.\n### Medium\nNone.\n### Low\nNo low-severity issues.\n"
		report, called, _ := postedTrailReport(t, reviewers, prose+oneHighComment)
		if !called || len(report.Comments) != 1 || report.Prose != "" {
			t.Fatalf("called=%v report=%+v, want the one structured comment and no prose", called, report)
		}
	})

	for name, prose := range map[string]string{
		"a bold summary after the finding": "### High\n- retry.go:42 unbounded retry loop.\n\n**Summary:** Solid change; fix the retry loop before merging.",
		"a bold verdict after the finding": "### High\n- retry.go:42 unbounded retry loop.\n\n**Verdict:** Request changes.",
	} {
		t.Run("comments covering "+name+" are posted as structured findings", func(t *testing.T) {
			t.Parallel()
			report, called, _ := postedTrailReport(t, reviewers, prose+"\n"+oneHighComment)
			if !called || len(report.Comments) != 1 || report.Prose != "" {
				t.Fatalf("called=%v report=%+v, want the one structured comment and no prose", called, report)
			}
		})
	}
}

