// The contract is trusted: a valid comments array is posted as is, even when
// the prose lists more findings than it holds.
func TestTrailReportTrustsTheContract(t *testing.T) {
	t.Parallel()
	for name, aggregate := range map[string]string{
		"more marked findings":  "request changes\n- [high] a.go:1 — A.\n- [high] b.go:2 — B.\n" + oneHighComment,
		"an uncovered location": "## High\n\n### Error handling\n- retry.go:42 the loop never stops.\n- auth.go:10 the token is logged.\n" + oneHighComment,
	} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			report, called, _ := postedTrailReport(t, judgeReviewers(), aggregate)
			if !called || len(report.Comments) != 1 || report.Prose != "" {
				t.Fatalf("called=%v report=%+v, want the one structured comment and no prose", called, report)
			}
		})
	}

	t.Run("without a judge", func(t *testing.T) {
		t.Parallel()
		run := textRun("claude-code", "request changes\n- [high] a.go:1 — A.\n- [high] b.go:2 — B.\n"+oneHighComment)
		report, called, _ := postedTrailReport(t, trailRunsSummary(run), "")
		if !called || len(report.Comments) != 1 || report.Prose != "" {
			t.Fatalf("called=%v report=%+v, want the one structured comment and no prose", called, report)
		}
	})

	t.Run("an unmarked bullet does not contradict an empty array", func(t *testing.T) {
		t.Parallel()
		_, called, out := postedTrailReport(t, judgeReviewers(), "approve\n- retry.go is tidy now\n"+emptyTrailJSON)
		requireNotPosted(t, called, out)
	})
}

